known_correct:
SELECT c.name,
       (SELECT COUNT(*) FROM orders o WHERE o.customer_id = c.id AND o.status = 'paid') AS paid_orders
FROM customers c;

SELECT name, price FROM (
  SELECT name, price, RANK() OVER (ORDER BY price DESC) AS r FROM products
) WHERE r = 1;

